SCENES.s5 = { id: 's5', title: 'a photo or a video?', app: 'slow', intro: 'Same page, same idea, two kinds of check. Watch which one survives a page that needs a moment.', steps: [
  { full: true, py: 'page.get_by_role("button", name="Load report").click()\nassert page.get_by_text("Report ready").is_visible()', kt: 'page.getByRole(AriaRole.BUTTON, Page.GetByRoleOptions().setName("Load report")).click()\nassertTrue(page.getByText("Report ready").isVisible())', say: 'The report needs 1.5 seconds. This check asks "is it visible?" <b>once</b>, a split second after the click, like a photo. The answer is no, so the test fails with an error, although nothing is wrong with the page.' },
  { full: true, py: 'page.get_by_role("button", name="Load report").click()\nexpect(page.get_by_text("Report ready")).to_be_visible()', kt: 'page.getByRole(AriaRole.BUTTON, Page.GetByRoleOptions().setName("Load report")).click()\nassertThat(page.getByText("Report ready")).isVisible()', say: 'The web-first assertion is like a <b>video</b>: it keeps looking until the condition is true or the time is over. It passed after 1500 ms. The test is the same length, and now it is correct.' },
  { py: 'expect(page.get_by_role("row")).to_have_count(3)', kt: 'assertThat(page.getByRole(AriaRole.ROW)).hasCount(3)', say: 'The same retrying works for counts, texts, values and more. Here the table has a header row and two data rows.' }
] };

