SCENES.s6 = { id: 's6', title: 'from repeated setup to a fixture', run: false, intro: 'Two tests repeat the same setup. Watch it move to one place. This is display only: the code runs on your computer, not in the lab.', steps: [
  { full: true,
    py: 'def test_two_items_left(page: Page):\n    page.goto("https://demo.playwright.dev/todomvc/")\n    new_todo = page.get_by_placeholder("What needs to be done?")\n    new_todo.fill("Buy milk")\n    new_todo.press("Enter")\n    new_todo.fill("Walk the dog")\n    new_todo.press("Enter")\n    expect(page.get_by_test_id("todo-count")).to_have_text("2 items left")\n\n\ndef test_one_left_after_completing(page: Page):\n    page.goto("https://demo.playwright.dev/todomvc/")\n    new_todo = page.get_by_placeholder("What needs to be done?")\n    new_todo.fill("Buy milk")\n    new_todo.press("Enter")\n    new_todo.fill("Walk the dog")\n    new_todo.press("Enter")\n    page.get_by_test_id("todo-item").first.get_by_role("checkbox").check()\n    expect(page.get_by_test_id("todo-count")).to_have_text("1 item left")',
    kt: '@Test\nfun twoItemsLeft() {\n    page.navigate("https://demo.playwright.dev/todomvc/")\n    val newTodo = page.getByPlaceholder("What needs to be done?")\n    newTodo.fill("Buy milk")\n    newTodo.press("Enter")\n    newTodo.fill("Walk the dog")\n    newTodo.press("Enter")\n    assertThat(page.getByTestId("todo-count")).hasText("2 items left")\n}\n\n@Test\nfun oneLeftAfterCompleting() {\n    page.navigate("https://demo.playwright.dev/todomvc/")\n    val newTodo = page.getByPlaceholder("What needs to be done?")\n    newTodo.fill("Buy milk")\n    newTodo.press("Enter")\n    newTodo.fill("Walk the dog")\n    newTodo.press("Enter")\n    page.getByTestId("todo-item").first().getByRole(AriaRole.CHECKBOX).check()\n    assertThat(page.getByTestId("todo-count")).hasText("1 item left")\n}',
    say: 'Two tests, and the same seven lines of setup in both. If the page changes, you must fix it twice, and with fifty tests, fifty times. Also, the real point of each test is buried in the noise.' },
  { full: true,
    py: '@pytest.fixture\ndef todo_page(page: Page) -> Page:\n    page.goto("https://demo.playwright.dev/todomvc/")\n    new_todo = page.get_by_placeholder("What needs to be done?")\n    for title in ["Buy milk", "Walk the dog"]:\n        new_todo.fill(title)\n        new_todo.press("Enter")\n    return page',
    kt: '@BeforeEach\nfun addTwoTodos() {\n    page.navigate("https://demo.playwright.dev/todomvc/")\n    val newTodo = page.getByPlaceholder("What needs to be done?")\n    for (title in listOf("Buy milk", "Walk the dog")) {\n        newTodo.fill(title)\n        newTodo.press("Enter")\n    }\n}',
    say: 'Move the setup to one place. In pytest it is a <b>fixture</b>: a function that prepares something and hands it to the tests that ask for it. In JUnit it is a method marked <code>@BeforeEach</code>, which runs before every test.' },
  { full: true,
    py: 'def test_two_items_left(todo_page: Page):\n    expect(todo_page.get_by_test_id("todo-count")).to_have_text("2 items left")\n\n\ndef test_one_left_after_completing(todo_page: Page):\n    todo_page.get_by_test_id("todo-item").first.get_by_role("checkbox").check()\n    expect(todo_page.get_by_test_id("todo-count")).to_have_text("1 item left")',
    kt: '@Test\nfun twoItemsLeft() {\n    assertThat(page.getByTestId("todo-count")).hasText("2 items left")\n}\n\n@Test\nfun oneLeftAfterCompleting() {\n    page.getByTestId("todo-item").first().getByRole(AriaRole.CHECKBOX).check()\n    assertThat(page.getByTestId("todo-count")).hasText("1 item left")\n}',
    say: 'Now each test says only what it is about. Each test still gets a brand new context, so the setup runs again for every test and nothing leaks from one test to the next.' }
] };

